contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address target) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(target != address(0));
        require(target != address(c));
        require(address(this).balance >= amount);

        uint cBefore = address(c).balance;
        uint targetBefore = target.balance;

        bool reverted;
        c.sendMoney(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (address(c).balance == cBefore - amount && target.balance == targetBefore + amount));
    }

    receive() external payable {}
}

